"use client";

import { useState } from "react";
import { motion } from "motion/react";
import {
  ArrowRight,
  Infinity,
  Shield,
  Sparkles,
  Zap,
} from "lucide-react";
import { cn } from "@/lib/utils";

interface Feature {
  icon: React.ReactNode;
  title: string;
  description: string;
  highlight?: boolean;
}

const features: Feature[] = [
  {
    icon: <Infinity className="h-4 w-4" />,
    title: "Unlimited Projects",
    description: "Create as many projects as you need",
    highlight: true,
  },
  {
    icon: <Shield className="h-4 w-4" />,
    title: "Enterprise Security",
    description: "Advanced security protocols & encryption",
  },
  {
    icon: <Zap className="h-4 w-4" />,
    title: "Priority Access",
    description: "Early access to new features",
    highlight: true,
  },
];

export default function Pricing_01() {
  const [isHovered, setIsHovered] = useState(false);

  return (
    <div className="mx-auto w-full max-w-sm">
      <motion.div
        initial={{ opacity: 0, y: 16 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.45, ease: [0.22, 1, 0.36, 1] }}
        className="group relative overflow-hidden rounded-2xl border border-white/[0.08] bg-[#09090B] shadow-[0_20px_60px_rgba(0,0,0,0.3)]"
      >
        <div className="pointer-events-none absolute -left-24 -top-24 h-56 w-56 rounded-full bg-violet-500/[0.10] blur-3xl" />

        <div className="relative flex items-center justify-between border-b border-white/[0.06] p-6">
          <div className="flex items-center gap-3">
            <div className="flex h-10 w-10 items-center justify-center rounded-xl border border-violet-400/[0.15] bg-violet-500/[0.08] text-violet-300">
              <Sparkles className="h-4 w-4" />
            </div>

            <div>
              <h3 className="text-sm font-semibold text-white">
                Enterprise Plan
              </h3>
              <p className="mt-0.5 text-xs text-zinc-500">
                For growing teams
              </p>
            </div>
          </div>

          <span className="rounded-full border border-violet-400/[0.15] bg-violet-500/[0.08] px-2.5 py-1 text-[10px] font-medium text-violet-300">
            Popular
          </span>
        </div>

        <div className="relative border-b border-white/[0.06] p-6">
          <div className="flex items-end gap-1.5">
            <span className="text-4xl font-semibold tracking-tight text-white">
              $49
            </span>
            <span className="mb-1 text-sm text-zinc-500">/month</span>
          </div>

          <p className="mt-2 text-sm leading-6 text-zinc-500">
            Everything you need to scale your business.
          </p>
        </div>

        <div className="relative space-y-2 p-4">
          {features.map((feature, index) => (
            <motion.div
              key={feature.title}
              initial={{ opacity: 0, x: -8 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: 0.08 * index }}
              className={cn(
                "flex items-start gap-3 rounded-xl border p-3 transition",
                feature.highlight
                  ? "border-violet-400/[0.10] bg-violet-500/[0.045]"
                  : "border-transparent hover:border-white/[0.06] hover:bg-white/[0.025]",
              )}
            >
              <div
                className={cn(
                  "flex h-8 w-8 shrink-0 items-center justify-center rounded-lg border",
                  feature.highlight
                    ? "border-violet-400/[0.15] bg-violet-500/[0.08] text-violet-300"
                    : "border-white/[0.07] bg-white/[0.025] text-zinc-500",
                )}
              >
                {feature.icon}
              </div>

              <div>
                <p className="text-sm font-medium text-zinc-200">
                  {feature.title}
                </p>
                <p className="mt-0.5 text-xs leading-5 text-zinc-600">
                  {feature.description}
                </p>
              </div>
            </motion.div>
          ))}
        </div>

        <div className="relative border-t border-white/[0.06] p-5">
          <motion.button
            type="button"
            onHoverStart={() => setIsHovered(true)}
            onHoverEnd={() => setIsHovered(false)}
            whileTap={{ scale: 0.985 }}
            className="flex h-11 w-full items-center justify-center gap-2 rounded-full bg-white text-sm font-medium text-black transition hover:bg-zinc-200"
          >
            Get started
            <motion.span
              animate={{ x: isHovered ? 3 : 0 }}
              transition={{ duration: 0.2 }}
            >
              <ArrowRight className="h-4 w-4" />
            </motion.span>
          </motion.button>
        </div>
      </motion.div>
    </div>
  );
}

"use client";

import { ArrowRight, Check, Minus } from "lucide-react";
import { cn } from "@/lib/utils";

interface Feature {
  name: string;
  highlight?: boolean;
  included: boolean;
}

interface PricingTier {
  name: string;
  price: number;
  description: string;
  features: Feature[];
  highlight?: boolean;
  cta?: string;
}

const defaultTiers: PricingTier[] = [
  {
    name: "SELF",
    price: 299,
    description: "For small teams and growing businesses",
    features: [
      { name: "Up to 20 team members", included: true },
      { name: "Advanced analytics", included: true },
      { name: "24/7 email support", included: true },
      { name: "API access", included: true, highlight: true },
      { name: "Custom integrations", included: false },
      { name: "Enterprise features", included: false },
    ],
    cta: "Get started",
  },
  {
    name: "TEAM",
    price: 999,
    description: "For large organizations and enterprises",
    highlight: true,
    features: [
      { name: "Unlimited team members", included: true },
      { name: "Advanced analytics", included: true },
      { name: "24/7 priority support", included: true },
      { name: "Unlimited API access", included: true, highlight: true },
      { name: "Custom integrations", included: true },
      { name: "Enterprise features", included: true },
    ],
    cta: "Get started",
  },
];

export default function Pricing_02({
  tiers = defaultTiers,
}: {
  tiers?: PricingTier[];
}) {
  return (
    <div className="mx-auto w-full max-w-5xl px-4">
      <div className="grid grid-cols-1 gap-5 md:grid-cols-2">
        {tiers.map((tier) => (
          <div
            key={tier.name}
            className={cn(
              "relative overflow-hidden rounded-2xl border bg-[#09090B] transition duration-300",
              tier.highlight
                ? "border-violet-400/[0.22] shadow-[0_20px_60px_rgba(124,58,237,0.08)]"
                : "border-white/[0.08] hover:border-white/[0.13]",
            )}
          >
            {tier.highlight && (
              <>
                <div className="absolute inset-x-16 top-0 h-px bg-gradient-to-r from-transparent via-violet-400/70 to-transparent" />
                <div className="pointer-events-none absolute -right-20 -top-24 h-52 w-52 rounded-full bg-violet-500/[0.08] blur-3xl" />
              </>
            )}

            <div className="relative flex h-full flex-col p-7 sm:p-8">
              <div>
                <div className="flex items-center justify-between">
                  <p className="text-xs font-medium tracking-[0.16em] text-zinc-500">
                    {tier.name}
                  </p>

                  {tier.highlight && (
                    <span className="rounded-full border border-violet-400/[0.15] bg-violet-500/[0.08] px-2.5 py-1 text-[10px] text-violet-300">
                      Recommended
                    </span>
                  )}
                </div>

                <div className="mt-6 flex items-end gap-2">
                  <span className="text-5xl font-medium tracking-[-0.05em] text-white">
                    ${tier.price}
                  </span>
                  <span className="mb-1.5 text-xs text-zinc-600">
                    one-time
                  </span>
                </div>

                <p className="mt-3 border-b border-white/[0.06] pb-6 text-sm leading-6 text-zinc-500">
                  {tier.description}
                </p>
              </div>

              <div className="mt-6 flex-1 space-y-4">
                {tier.features.map((feature) => (
                  <div
                    key={feature.name}
                    className="flex items-center gap-3"
                  >
                    <div
                      className={cn(
                        "flex h-5 w-5 shrink-0 items-center justify-center rounded-full border",
                        feature.included
                          ? feature.highlight
                            ? "border-violet-400/[0.25] bg-violet-500/[0.10] text-violet-300"
                            : "border-white/[0.10] bg-white/[0.04] text-zinc-300"
                          : "border-white/[0.05] text-zinc-700",
                      )}
                    >
                      {feature.included ? (
                        <Check className="h-3 w-3" />
                      ) : (
                        <Minus className="h-3 w-3" />
                      )}
                    </div>

                    <span
                      className={cn(
                        "text-sm",
                        feature.included
                          ? "text-zinc-400"
                          : "text-zinc-700",
                      )}
                    >
                      {feature.name}
                    </span>
                  </div>
                ))}
              </div>

              <button
                type="button"
                className={cn(
                  "mt-8 flex h-11 w-full items-center justify-center gap-2 rounded-full text-sm font-medium transition",
                  tier.highlight
                    ? "bg-white text-black hover:bg-zinc-200"
                    : "border border-white/[0.09] bg-white/[0.035] text-zinc-200 hover:bg-white/[0.07]",
                )}
              >
                {tier.cta}
                <ArrowRight className="h-4 w-4" />
              </button>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
}

"use client";

import { useState } from "react";
import { ArrowRight, Check, Minus } from "lucide-react";
import { cn } from "@/lib/utils";

interface Feature {
  name: string;
  included: "starter" | "pro" | "all" | null;
}

const features: Feature[] = [
  { name: "Basic Analytics", included: "starter" },
  { name: "Up to 5 team members", included: "starter" },
  { name: "Basic support", included: "starter" },
  { name: "Advanced Analytics", included: "pro" },
  { name: "Up to 20 team members", included: "pro" },
  { name: "Priority support", included: "pro" },
  { name: "Custom integrations", included: "all" },
  { name: "Unlimited team members", included: "all" },
  { name: "24/7 phone support", included: "all" },
];

const plans = [
  {
    name: "Starter",
    price: { monthly: 15, yearly: 144 },
    level: "starter" as const,
  },
  {
    name: "Pro",
    price: { monthly: 49, yearly: 470 },
    level: "pro" as const,
  },
  {
    name: "Enterprise",
    price: { monthly: 99, yearly: 990 },
    level: "all" as const,
  },
];

export default function Pricing_03() {
  const [isYearly, setIsYearly] = useState(false);
  const [selectedPlan, setSelectedPlan] = useState<string>("pro");

  return (
    <div className="mx-auto w-full max-w-4xl px-4">
      <div className="mb-6 flex justify-center sm:justify-end">
        <div className="inline-flex rounded-full border border-white/[0.08] bg-white/[0.025] p-1">
          {["Monthly", "Yearly"].map((period) => {
            const active =
              period === "Yearly" ? isYearly : !isYearly;

            return (
              <button
                key={period}
                type="button"
                onClick={() => setIsYearly(period === "Yearly")}
                className={cn(
                  "rounded-full px-4 py-1.5 text-xs transition",
                  active
                    ? "bg-white text-black"
                    : "text-zinc-500 hover:text-zinc-200",
                )}
              >
                {period}
              </button>
            );
          })}
        </div>
      </div>

      <div className="mb-5 grid grid-cols-1 gap-3 sm:grid-cols-3">
        {plans.map((plan) => {
          const selected = selectedPlan === plan.level;

          return (
            <button
              key={plan.level}
              type="button"
              onClick={() => setSelectedPlan(plan.level)}
              className={cn(
                "relative rounded-xl border p-4 text-left transition",
                selected
                  ? "border-violet-400/[0.28] bg-violet-500/[0.06] shadow-[0_0_30px_rgba(139,92,246,0.06)]"
                  : "border-white/[0.07] bg-[#09090B] hover:border-white/[0.12]",
              )}
            >
              <div className="flex items-center justify-between">
                <span className="text-sm font-medium text-zinc-300">
                  {plan.name}
                </span>

                {plan.level === "pro" && (
                  <span className="rounded-full bg-violet-500/[0.10] px-2 py-0.5 text-[9px] text-violet-300">
                    Popular
                  </span>
                )}
              </div>

              <div className="mt-3">
                <span className="text-2xl font-semibold text-white">
                  ${isYearly ? plan.price.yearly : plan.price.monthly}
                </span>
                <span className="ml-1 text-xs text-zinc-600">
                  /{isYearly ? "year" : "month"}
                </span>
              </div>
            </button>
          );
        })}
      </div>

      <div className="overflow-hidden rounded-2xl border border-white/[0.08] bg-[#09090B]">
        <div className="overflow-x-auto">
          <div className="min-w-[650px]">
            <div className="grid grid-cols-[1fr_repeat(3,90px)] items-center border-b border-white/[0.06] bg-white/[0.018] px-5 py-4">
              <span className="text-xs font-medium text-zinc-400">
                Features
              </span>

              {plans.map((plan) => (
                <span
                  key={plan.level}
                  className={cn(
                    "text-center text-xs",
                    selectedPlan === plan.level
                      ? "font-medium text-violet-300"
                      : "text-zinc-600",
                  )}
                >
                  {plan.name}
                </span>
              ))}
            </div>

            {features.map((feature) => (
              <div
                key={feature.name}
                className="grid grid-cols-[1fr_repeat(3,90px)] items-center border-b border-white/[0.045] px-5 py-4 last:border-0"
              >
                <span className="text-sm text-zinc-500">
                  {feature.name}
                </span>

                {plans.map((plan) => {
                  const included = shouldShowCheck(
                    feature.included,
                    plan.level,
                  );

                  return (
                    <div
                      key={plan.level}
                      className="flex justify-center"
                    >
                      {included ? (
                        <div
                          className={cn(
                            "flex h-5 w-5 items-center justify-center rounded-full",
                            selectedPlan === plan.level
                              ? "bg-violet-500/[0.12] text-violet-300"
                              : "text-zinc-500",
                          )}
                        >
                          <Check className="h-3.5 w-3.5" />
                        </div>
                      ) : (
                        <Minus className="h-3.5 w-3.5 text-zinc-800" />
                      )}
                    </div>
                  );
                })}
              </div>
            ))}
          </div>
        </div>
      </div>

      <div className="mt-6 flex justify-center">
        <button
          type="button"
          className="flex h-11 w-full items-center justify-center gap-2 rounded-full bg-white px-7 text-sm font-medium text-black transition hover:bg-zinc-200 sm:w-auto"
        >
          Get started with{" "}
          {plans.find((plan) => plan.level === selectedPlan)?.name}
          <ArrowRight className="h-4 w-4" />
        </button>
      </div>
    </div>
  );
}

function shouldShowCheck(
  included: Feature["included"],
  level: string,
): boolean {
  if (included === "all") return true;

  if (
    included === "pro" &&
    (level === "pro" || level === "all")
  ) {
    return true;
  }

  if (
    included === "starter" &&
    (level === "starter" || level === "pro" || level === "all")
  ) {
    return true;
  }

  return false;
}

