  description: string;
  features: string[];
  highlight?: boolean;
}

const defaultTiers: PricingTier[] = [
  {
    name: "Basic",
    price: 9,
    description: "Essential features for small teams",
    features: [
      "5 Team Members",
      "Basic Analytics",
      "Community Support",
      "1GB Storage",
    ],
  },
  {
    name: "Pro",
    price: 29,
    description: "Everything you need to scale",
    highlight: true,
    features: [
      "Unlimited Members",
      "Advanced Analytics",
      "Priority Support",
      "Unlimited Storage",
      "Custom Integrations",
    ],
  },
];

export default function Pricing_05() {
  return (
    <div className="mx-auto w-full max-w-3xl px-4">
      <div className="grid grid-cols-1 gap-5 md:grid-cols-2">
        {defaultTiers.map((tier) => (
          <div
            key={tier.name}
            className={cn(
